class Solution:
    def weightedSum(self, parent: List[int], nums: List[int]) -> int:
        n = len(parent)
        ch = [[] for _ in range(n)]
        for i in range(1, n):
            ch[parent[i]].append(i)
        depth = [0] * n
        depth[0] = 1
        q = [0]
        for u in q:
            for v in ch[u]:
                depth[v] = depth[u] + 1
                q.append(v)
        h = max(depth)
        return sum(nums[i] * (h - depth[i] + 1) for i in range(n))

