class Solution {
    public long weightedSum(int[] parent, int[] nums) {
        int n = parent.length;
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < n; i++) ch.get(parent[i]).add(i);
        int[] depth = new int[n];
        depth[0] = 1;
        int[] q = new int[n];
        int head = 0, tail = 0;
        q[tail++] = 0;
        while (head < tail) {
            int u = q[head++];
            for (int v : ch.get(u)) { depth[v] = depth[u] + 1; q[tail++] = v; }
        }
        int h = 0;
        for (int d : depth) h = Math.max(h, d);
        long ans = 0;
        for (int i = 0; i < n; i++) ans += (long) nums[i] * (h - depth[i] + 1);
        return ans;
    }
}

